'use client'

import { MorphingText } from '@/components/spaceui/morphing-text'
import { Animoji } from '@/components/spaceui/animoji'

const PHRASES = ['Ship faster 🚀', 'Design better ✨', 'Ship with confidence 🎉', 'Build with care 🛠️']

export default function Demo() {
  return (
    <div className="flex w-full items-center justify-center px-6 py-8">
      <MorphingText
        texts={PHRASES}
        renderChar={(char) => <Animoji>{char}</Animoji>}
        textClassName="text-2xl sm:text-3xl"
      />
    </div>
  )
}
